@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{--ink:#121c1d;--paper:#f1f1e8;--acid:#d5f064;--mint:#9ae1c4;--muted:#91a09c;--line:rgba(233,242,219,.13)}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#101819;color:var(--paper);font-family:'Outfit',sans-serif}body{min-height:100svh;background:radial-gradient(ellipse at 68% 45%,#1d3030 0,#121d1e 45%,#0e1718 85%);overflow-x:hidden}.game-shell{max-width:1440px;margin:auto;padding:0 6.15%}.topbar{height:86px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.13em}.brand{display:flex;align-items:center;gap:11px;color:#f5f5e8;text-decoration:none;font:800 16px 'Outfit',sans-serif;letter-spacing:.06em}.brand-mark{display:grid;place-items:center;width:28px;height:28px;color:#172222;background:var(--acid);border-radius:8px;font-size:17px}.brand-light{font-weight:500;color:#a6b5ad;margin-left:4px}.top-note{color:#8f9b95}.top-note i{font-style:normal;color:#52605b;margin:0 8px}.live-dot,.footer-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#d5f064;margin-right:8px;box-shadow:0 0 10px #d5f06480}.sound-button{border:1px solid var(--line);border-radius:30px;background:transparent;color:#9eaca5;padding:10px 14px;letter-spacing:.1em;font:10px 'DM Mono',monospace;cursor:pointer}.sound-button span:first-child{color:var(--acid);font-size:13px;margin-right:7px}.sound-button.off{opacity:.55}.game-layout{display:grid;grid-template-columns:235px minmax(0,800px);gap:clamp(35px,8vw,112px);justify-content:center;align-items:center;padding:50px 0 42px}.side-copy{align-self:center;padding:4px 0 0}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.14em;color:#9aa8a0;margin:0 0 20px}.eyebrow span{color:var(--acid);padding-left:5px}.side-copy h1{font-size:clamp(50px,5.6vw,74px);line-height:.91;letter-spacing:-.06em;margin:0;font-weight:800}.side-copy h1 em{font-style:normal;color:var(--acid)}.description{color:#aab5ac;font-size:14px;line-height:1.55;margin:22px 0 0}.description strong{color:#e6edda;font-weight:600}.howto{display:flex;align-items:flex-start;gap:13px;margin:37px 0 31px}.howto-icon{display:grid;place-items:center;flex:none;width:29px;height:29px;border:1px solid #536359;border-radius:50%;color:var(--acid);font-size:16px}.howto p{margin:0;color:#91a099;font-size:11px;line-height:1.7}.howto b{font:10px 'DM Mono',monospace;letter-spacing:.1em;color:#e3e9db}.personal-best{border-top:1px solid var(--line);padding-top:17px;display:flex;align-items:center;gap:12px;position:relative}.personal-best span:first-child{font:9px 'DM Mono',monospace;letter-spacing:.11em;color:#83928a}.personal-best b{font:500 19px 'DM Mono',monospace;letter-spacing:.06em;color:#eff4e5}.personal-best .best-star{color:var(--acid);font-size:12px}.board-wrap{min-width:0;width:100%;max-width:800px}.game-frame{position:relative;width:100%;aspect-ratio:1.34/1;min-height:360px;max-height:590px;overflow:hidden;border:1px solid rgba(220,237,211,.18);border-radius:14px;background:#243432;box-shadow:0 30px 90px #050b0b80, inset 0 0 0 5px #142020}.game-frame:after{content:'';position:absolute;inset:0;pointer-events:none;border-radius:14px;box-shadow:inset 0 0 70px #09121266}.game-frame canvas{display:block;width:100%;height:100%;touch-action:none;cursor:crosshair}.hud{position:absolute;top:17px;left:20px;right:20px;z-index:2;display:flex;align-items:flex-start;pointer-events:none}.hud-block{display:flex;flex-direction:column;gap:3px;min-width:78px}.hud-block span{font:9px 'DM Mono',monospace;letter-spacing:.13em;color:#d4dfcaad}.hud-block strong{font:600 23px 'DM Mono',monospace;letter-spacing:.02em;color:#f8f6e8;text-shadow:0 2px 6px #101818}.hud-block small{position:absolute;top:42px;font:10px 'DM Mono',monospace;color:var(--acid);opacity:0;transform:translateY(4px);transition:.2s}.hud-block small.show{opacity:1;transform:translateY(0)}.combo-block{position:absolute;left:50%;transform:translateX(-50%);align-items:center;padding:5px 13px 6px;border-radius:20px;background:#101b1ca6;border:1px solid #ecf6dd22;transition:transform .2s,border .2s}.combo-block strong{color:var(--acid);font-size:18px}.combo-block.hot{transform:translateX(-50%) scale(1.15);border-color:#d5f06499}.time-block{margin-left:auto;text-align:right}.time-block strong{font-size:24px}.time-block.urgent strong{color:#ff8269}.lives{position:absolute;left:50%;top:70px;transform:translateX(-50%);display:flex;gap:5px;font-size:12px;color:#ff8171;text-shadow:0 0 10px #ff5f5988}.lives .lost{opacity:.2;filter:grayscale(1)}.board-footer{height:45px;display:flex;align-items:center;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#829189}.board-footer b{color:#c9d5bd;font-weight:500}.board-footer span:first-child b{color:var(--acid)}.board-footer button{font:9px 'DM Mono',monospace;color:#92a098;border:0;background:none;cursor:pointer;letter-spacing:.12em;padding:8px 0}.board-footer button span{margin-left:5px}.page-footer{display:flex;justify-content:space-between;padding:20px 0;border-top:1px solid var(--line);font:9px 'DM Mono',monospace;letter-spacing:.11em;color:#728079}.page-footer b{color:#bdc9bc;font-weight:500}.footer-spark{color:var(--acid);padding-left:5px}.overlay{position:absolute;inset:0;z-index:4;display:grid;place-items:center;background:rgba(13,24,24,.44);backdrop-filter:blur(4px);transition:opacity .25s,visibility .25s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-card{text-align:center;width:min(90%,400px);padding:20px 20px 14px;border:1px solid #e8f4dc27;border-radius:16px;background:linear-gradient(145deg,#172624ed,#182524e8);box-shadow:0 24px 80px #07101090}.overlay-kicker{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#a9b5a8}.overlay-kicker span{color:var(--acid);padding:0 6px}.hero-fruits{height:64px;display:flex;align-items:center;justify-content:center;gap:9px;margin:6px 0 0}.hero-fruits span{font-size:33px;filter:drop-shadow(0 7px 7px #07101075);animation:bob 2s ease-in-out infinite}.hero-fruits span:nth-child(2){animation-delay:.2s;transform:rotate(12deg)}.hero-fruits span:nth-child(3){animation-delay:.4s}.hero-fruits span:nth-child(4){animation-delay:.6s}@keyframes bob{0%,100%{translate:0 0}50%{translate:0 -6px}}.overlay h2{font-size:42px;line-height:.95;letter-spacing:-.055em;margin:8px 0 10px;font-weight:800}.overlay h2 em{font-style:normal;color:var(--acid)}.overlay p{font-size:12px;color:#aab7ac;line-height:1.5;margin:0 0 17px}.play-button{display:flex;align-items:center;justify-content:space-between;width:210px;margin:auto;border:0;border-radius:8px;background:var(--acid);color:#15201b;padding:12px 14px 12px 19px;font:700 11px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer;transition:transform .15s,background .15s}.play-button:hover{transform:translateY(-2px);background:#e2ff77}.play-button b{display:grid;place-items:center;width:23px;height:23px;border-radius:5px;background:#17231c;color:var(--acid);font-size:15px}.overlay-hint{margin-top:15px;color:#829187;font:8px 'DM Mono',monospace;letter-spacing:.11em}.overlay-hint span{padding:0 5px;color:var(--acid)}.pause-indicator{position:absolute;z-index:3;inset:0;display:none;place-content:center;gap:17px;text-align:center;background:#111b1dcc;backdrop-filter:blur(3px);font:700 24px 'DM Mono',monospace;letter-spacing:.15em}.pause-indicator.visible{display:grid}.pause-indicator button{border:0;background:transparent;color:var(--acid);font:11px 'DM Mono',monospace;letter-spacing:.1em;cursor:pointer}.combo-toast{position:absolute;z-index:3;left:50%;top:34%;transform:translate(-50%,10px) scale(.8);color:#e8ff84;font:800 26px 'Outfit',sans-serif;letter-spacing:.04em;text-shadow:0 3px 20px #d5f0649c;opacity:0;pointer-events:none;transition:all .22s}.combo-toast.show{opacity:1;transform:translate(-50%,-4px) scale(1)}
@media(max-width:850px){.game-shell{padding:0 4%}.game-layout{grid-template-columns:170px minmax(0,1fr);gap:30px}.side-copy h1{font-size:56px}.game-frame{min-height:330px}.topbar{height:72px}}
@media(max-width:650px){body{background:radial-gradient(ellipse at 55% 40%,#203131 0,#111c1d 75%)}.game-shell{padding:0 16px}.topbar{height:62px}.brand{font-size:14px}.top-note{display:none}.sound-button{padding:8px 10px}.sound-label{font-size:8px}.game-layout{display:flex;flex-direction:column-reverse;gap:14px;padding:18px 0 12px;align-items:stretch}.side-copy{display:grid;grid-template-columns:1fr auto;align-items:center;column-gap:8px;padding:0 2px}.side-copy .eyebrow,.side-copy h1,.side-copy .description,.howto{display:none}.personal-best{border:0;padding:0;gap:7px;justify-content:flex-end}.personal-best span:first-child{font-size:8px}.personal-best b{font-size:14px}.personal-best .best-star{font-size:10px}.side-copy:before{content:'SLICE. CHAIN. SHINE.';font-size:12px;letter-spacing:.1em;font-weight:700;color:#e9efdf}.game-frame{aspect-ratio:.86/1;min-height:0;max-height:none;border-radius:12px}.game-frame:after{border-radius:12px}.hud{top:14px;left:14px;right:14px}.hud-block{min-width:62px}.hud-block strong{font-size:20px}.hud-block span{font-size:8px}.lives{top:62px}.combo-block{top:0}.board-footer{height:37px;font-size:8px}.board-footer button{font-size:8px}.page-footer{padding:13px 0;font-size:7px;line-height:1.6;gap:12px}.page-footer span:last-child{text-align:right}.overlay-card{padding:16px 14px 12px}.hero-fruits{height:52px}.hero-fruits span{font-size:29px}.overlay h2{font-size:36px}.overlay p{font-size:11px}.play-button{padding:10px 12px 10px 16px}.overlay-hint{font-size:7px}}
@media(max-height:700px) and (min-width:651px){.game-layout{padding:22px 0}.game-frame{min-height:0;max-height:calc(100vh - 190px)}.side-copy h1{font-size:56px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { score:$('score'), time:$('time'), combo:$('combo'), comboHud:$('comboHud'), lives:$('lives'), overlay:$('overlay'), title:$('overlayTitle'), text:$('overlayText'), play:$('playBtn'), playLabel:$('playLabel'), toast:$('comboToast'), delta:$('scoreDelta'), pause:$('pauseIndicator'), bestSide:$('bestSide'), bestChain:$('bestChain'), timeBlock:document.querySelector('.time-block'), sound:$('soundBtn'), soundIcon:$('soundIcon') };
  const FRUITS = [
    {name:'CITRUS',color:'#ff9f38',light:'#ffd46f',dark:'#df622e',leaf:'#7fc96d'},
    {name:'WATERMELON',color:'#ef6470',light:'#ff9c8b',dark:'#bf4059',leaf:'#65c88b'},
    {name:'LEMON',color:'#f5d84c',light:'#fff18b',dark:'#d6a82e',leaf:'#81bc69'},
    {name:'KIWI',color:'#95c66b',light:'#c9df81',dark:'#588e58',leaf:'#5eaa6e'},
    {name:'BERRY',color:'#dc577e',light:'#ff9bb5',dark:'#a83367',leaf:'#73b978'},
    {name:'PEACH',color:'#f2956d',light:'#ffd18b',dark:'#db6657',leaf:'#70b875'}
  ];
  const state = { running:false, paused:false, ended:false, score:0, best:Number(localStorage.getItem('fruitfrenzy-best')||0), lives:3, time:60, combo:1, chain:0, bestChain:0, chainUntil:0, lastSwipe:0, spawnIn:0, elapsed:0, shake:0, fruits:[], particles:[], halves:[], trails:[], popups:[], pointer:null, sound:true, lastFrame:0, screen:{w:800,h:590}, comboToastUntil:0, firstWave:true };
  let audio;
  ui.bestSide.textContent = String(state.best).padStart(4,'0');

  function resize(){
    const r=canvas.getBoundingClientRect(); const dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.max(1,Math.round(r.width*dpr)); canvas.height=Math.max(1,Math.round(r.height*dpr));
    state.screen.w=r.width; state.screen.h=r.height; ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  new ResizeObserver(resize).observe(canvas); resize();
  function sound(freq=440,duration=.08,type='sine',volume=.035){
    if(!state.sound)return;
    try{audio ||= new (window.AudioContext||window.webkitAudioContext)(); if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(100,freq*.62),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch(e){}
  }
  function rand(a,b){return a+Math.random()*(b-a)}
  function spawnWave(){
    const w=state.screen.w,h=state.screen.h; const count=Math.min(5,2+Math.floor(state.elapsed/13)+Math.floor(Math.random()*2));
    const center=rand(w*.31,w*.69), direction=Math.random()<.5?-1:1;
    for(let i=0;i<count;i++){
      const bomb=!state.firstWave && Math.random()<Math.min(.2,.07+state.elapsed/500);
      const x=center+(i-(count-1)/2)*rand(39,53), y=h+rand(25,75);
      state.fruits.push({x,y,vx:direction*rand(65,145)+rand(-35,35),vy:-rand(h*.92,h*1.22),r:rand(22,29),rot:rand(-.4,.4),vr:rand(-2.2,2.2),type:bomb?'bomb':'fruit',fruit:FRUITS[Math.floor(Math.random()*FRUITS.length)],cut:false,seed:Math.random()*10});
    }
    state.firstWave=false;
  }
  function start(){
    state.running=true;state.paused=false;state.ended=false;state.score=0;state.lives=3;state.time=60;state.combo=1;state.chain=0;state.bestChain=0;state.chainUntil=0;state.elapsed=0;state.fruits=[];state.particles=[];state.halves=[];state.trails=[];state.popups=[];state.spawnIn=.25;state.firstWave=true;
    ui.score.textContent='0000';ui.time.textContent='60';ui.combo.textContent='×1';ui.bestChain.textContent='—';ui.overlay.classList.add('hidden');ui.pause.classList.remove('visible');ui.timeBlock.classList.remove('urgent');updateLives();sound(520,.12,'triangle',.04);
  }
  function endGame(){
    if(state.ended)return;state.running=false;state.ended=true;
    if(state.score>state.best){state.best=state.score;localStorage.setItem('fruitfrenzy-best',state.best);ui.bestSide.textContent=String(state.best).padStart(4,'0');}
    ui.title.innerHTML=state.score>=state.best?'New best!<br><em>That's juicy.</em>':'Nice slicing.<br><em>One more?</em>';
    ui.text.innerHTML=`You scored <b style="color:#d5f064">${String(state.score).padStart(4,'0')}</b> points.<br>Best chain: ${state.bestChain||1}×. The orchard awaits.`;
    ui.playLabel.textContent='PLAY AGAIN';ui.overlay.classList.remove('hidden');sound(180,.2,'triangle',.045);
  }
  function updateLives(){[...ui.lives.children].forEach((el,i)=>el.classList.toggle('lost',i>=state.lives));ui.lives.setAttribute('aria-label',`${state.lives} lives`);if(state.lives<=0)endGame();}
  function loseLife(x,y){if(state.lives<=0)return;state.lives--;state.shake=12;state.popups.push({x,y,text:'− HEART',life:.8,color:'#ff8a78'});sound(145,.18,'sawtooth',.035);updateLives();}
  function updateHud(){ui.score.textContent=String(state.score).padStart(4,'0');ui.time.textContent=String(Math.ceil(state.time)).padStart(2,'0');ui.combo.textContent=`×${state.combo}`;ui.comboHud.classList.toggle('hot',state.combo>=3);ui.timeBlock.classList.toggle('urgent',state.time<=10);}
  function slice(f,dir){
    if(f.type==='bomb'){f.cut=true;loseLife(f.x,f.y);for(let n=0;n<18;n++)particle(f.x,f.y,Math.random()<.5?'#ff8b67':'#ffce67',rand(2,5));return;}
    f.cut=true;const now=performance.now();state.chain=now<state.chainUntil?state.chain+1:1;state.chainUntil=now+1250;state.combo=Math.min(9,state.chain);state.bestChain=Math.max(state.bestChain,state.combo);ui.bestChain.textContent=state.bestChain>1?`×${state.bestChain}`:'—';
    const points=10*state.combo;state.score+=points;ui.delta.textContent=`+${points}`;ui.delta.classList.remove('show');void ui.delta.offsetWidth;ui.delta.classList.add('show');
    const fcfg=f.fruit;for(let n=0;n<13;n++)particle(f.x,f.y,[fcfg.light,fcfg.color,fcfg.dark,'#f8f2d5'][n%4],rand(1.7,4.2));
    state.halves.push({x:f.x,y:f.y,vy:f.vy*.35,vx:f.vx*.6,rot:f.rot,vr:dir*.9,life:1,r:f.r,color:fcfg.color,light:fcfg.light,seed:f.seed});
    state.popups.push({x:f.x,y:f.y-10,text:`+${points}`,life:.75,color:state.combo>=3?'#e6fb7a':'#fff4cf'});
    if(state.combo>=3){state.comboToastUntil=now+550;ui.toast.textContent=state.combo>=5?'JUICE STORM!':`${state.combo}× CHAIN!`;ui.toast.classList.add('show');}
    sound(state.combo>=3?700:530,.07,'triangle',.025);
  }
  function particle(x,y,color,s){state.particles.push({x,y,vx:rand(-220,220),vy:rand(-210,160),life:rand(.35,.8),max:.8,r:s,color});}
  function distanceToSegment(p,a,b){const dx=b.x-a.x,dy=b.y-a.y;const t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-(a.x+t*dx),p.y-(a.y+t*dy));}
  function pointerDown(e){e.preventDefault();canvas.setPointerCapture?.(e.pointerId);const r=canvas.getBoundingClientRect();state.pointer={x:e.clientX-r.left,y:e.clientY-r.top};state.trails.push({x:state.pointer.x,y:state.pointer.y,life:.2});}
  function pointerMove(e){if(!state.pointer||!state.running||state.paused)return;e.preventDefault();const r=canvas.getBoundingClientRect(),next={x:e.clientX-r.left,y:e.clientY-r.top};const speed=Math.hypot(next.x-state.pointer.x,next.y-state.pointer.y);if(speed>2){state.trails.push({x:next.x,y:next.y,life:.24});for(const f of state.fruits){if(!f.cut&&distanceToSegment(f,state.pointer,next)<f.r*.88)slice(f,Math.sign(next.x-state.pointer.x)||1);}}state.pointer=next;}
  function pointerUp(){state.pointer=null;}
  canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);window.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);

  function update(dt,now){
    if(!state.running||state.paused)return;
    state.elapsed+=dt;state.time=Math.max(0,state.time-dt);if(state.time===0){endGame();return;}
    state.spawnIn-=dt;if(state.spawnIn<=0){spawnWave();state.spawnIn=Math.max(.56,rand(1.05,1.5)-state.elapsed*.006);}
    if(now>state.chainUntil){state.combo=1;}
    if(now>state.comboToastUntil)ui.toast.classList.remove('show');
    for(let i=state.fruits.length-1;i>=0;i--){const f=state.fruits[i];f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=480*dt;f.rot+=f.vr*dt;if(f.cut){state.fruits.splice(i,1);continue;}if(f.y>state.screen.h+f.r){state.fruits.splice(i,1);if(f.type==='fruit')loseLife(f.x,state.screen.h-15);}}
    for(const p of state.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=380*dt;p.life-=dt;}state.particles=state.particles.filter(p=>p.life>0);
    for(const h of state.halves){h.x+=h.vx*dt;h.y+=h.vy*dt;h.vy+=450*dt;h.rot+=h.vr*dt;h.life-=dt*.72;}state.halves=state.halves.filter(h=>h.life>0);
    for(const t of state.trails)t.life-=dt;state.trails=state.trails.filter(t=>t.life>0);
    for(const p of state.popups){p.y-=27*dt;p.life-=dt;}state.popups=state.popups.filter(p=>p.life>0);
    state.shake=Math.max(0,state.shake-dt*28);updateHud();
  }
  function drawBackground(w,h){
    const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#2d4540');g.addColorStop(.52,'#304743');g.addColorStop(1,'#243936');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
    ctx.save();ctx.globalAlpha=.12;for(let i=0;i<8;i++){const x=((i*137+34)%w),y=((i*93+80)%h);ctx.beginPath();ctx.ellipse(x,y,rand(28,66),rand(7,15),rand(-1,1),0,Math.PI*2);ctx.fillStyle=i%2?'#b9d688':'#e0e9b0';ctx.fill();}ctx.restore();
    ctx.strokeStyle='#d5e1be0b';ctx.lineWidth=1;for(let i=0;i<10;i++){ctx.beginPath();ctx.moveTo(i*w/9,0);ctx.lineTo((i*w/9)-40,h);ctx.stroke();}
    const vignette=ctx.createRadialGradient(w*.5,h*.48,h*.1,w*.5,h*.48,h*.75);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#101a1a66');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);
  }
  function drawFruit(f){
    ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.rot);
    if(f.type==='bomb'){
